#include <cstdint>
#include <cstdio>
#include <iostream>
#include <string>

using namespace std;

uint32_t fnv1a(const string& matn) {
    uint32_t h = 2166136261u;
    for (unsigned char b : matn) h = (h ^ b) * 16777619u;
    return h;
}

int main() {
    string yozuv;
    if (getline(cin, yozuv)) {
        if (!yozuv.empty() && yozuv.back() == '\r') yozuv.pop_back();
        char buf[16];
        snprintf(buf, sizeof buf, "%08x", fnv1a(yozuv));
        cout << buf << endl;
    }
    return 0;
}
